<template><div class="page-container"><div class="page-header"><div><h2>渠道验收工作台</h2><p>集中核对关键字段、数据新鲜度和页面完整性；复核、审核 SLA 在开发阶段保持关闭。</p></div></div>
  <el-alert type="warning" :closable="false" title="Jira API 仅只读同步；原始工单通过外链查看，任何平台处置、字段配置或验收结论都不会写回 Jira。"/>
  <div class="cards"><el-card v-for="item in channels" :key="item.sourceChannel" shadow="never"><template #header><b>{{labels[item.sourceChannel]||item.sourceChannel}}</b></template><p>数据量：{{item.data?.total??'—'}}</p><p>最新数据：{{item.data?.latestDataAt??'—'}}</p><p>验收状态：{{item.acceptance?.status??'未验收'}}</p><p class="muted">{{item.acceptance?.comment||'暂无验收意见'}}</p><el-button type="primary" plain @click="open(item.sourceChannel)">配置与验收</el-button></el-card></div>
  <el-drawer v-model="visible" size="680px" :title="`${labels[current]||current}：字段配置与验收`"><el-table :data="fields"><el-table-column prop="label" label="显示名称"><template #default="{row}"><el-input v-model="row.label"/></template></el-table-column><el-table-column prop="key" label="字段键"/><el-table-column label="显示" width="90"><template #default="{row}"><el-switch v-model="row.visible" :disabled="required.has(row.key)"/></template></el-table-column></el-table><el-input v-model="configReason" class="block" placeholder="配置变更原因"/><el-space><el-button @click="saveDraft">保存草稿</el-button><el-button type="primary" :disabled="!draftVersion" @click="publish">发布配置</el-button></el-space><el-divider>页面验收</el-divider><el-select v-model="acceptanceStatus"><el-option label="通过" value="PASSED"/><el-option label="有条件通过" value="CONDITIONAL"/><el-option label="不通过" value="REJECTED"/></el-select><el-input v-model="acceptanceComment" class="block" type="textarea" :rows="4" placeholder="验收意见"/><el-button type="primary" @click="accept">提交验收结论</el-button></el-drawer>
</div></template>
<script setup lang="ts">
import {onMounted,ref} from 'vue';import {ElMessage} from 'element-plus';import {getChannelGovernanceOverview,getChannelViewConfig,publishChannelViewConfig,saveChannelViewDraft,submitChannelAcceptance} from '@/api/channelGovernance'
const labels:Record<string,string>={ALL:'全部渠道',SDK:'SDK',STATION_FEEDBACK:'学习机反馈',JIRA:'Jira',QUALITY:'质量平台',RED_BLACK:'红黑榜'},required=new Set(['sourceEventTime','problem','processingStatus','distributionStatus','ownerName','lastHandledAt','resolved'])
const channels=ref<any[]>([]),fields=ref<any[]>([]),visible=ref(false),current=ref('ALL'),configReason=ref(''),draftVersion=ref(0),acceptanceStatus=ref('PASSED'),acceptanceComment=ref('')
async function load(){const r:any=await getChannelGovernanceOverview();channels.value=r.channels||[]}
async function open(channel:string){current.value=channel;const r:any=await getChannelViewConfig(channel);fields.value=typeof r.fields==='string'?JSON.parse(r.fields):r.fields;visible.value=true}
async function saveDraft(){if(configReason.value.trim().length<2)return ElMessage.warning('请填写配置变更原因');const r:any=await saveChannelViewDraft(current.value,fields.value,configReason.value);draftVersion.value=r.configVersion;ElMessage.success('草稿已保存，正式页面尚未变化')}
async function publish(){await publishChannelViewConfig(current.value,draftVersion.value);ElMessage.success('渠道默认字段配置已发布');draftVersion.value=0}
async function accept(){if(acceptanceComment.value.trim().length<2)return ElMessage.warning('请填写验收意见');await submitChannelAcceptance(current.value,acceptanceStatus.value,acceptanceComment.value);ElMessage.success('验收结论已记录');await load()}
onMounted(load)
</script>
<style scoped>.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:14px;margin-top:16px}.muted{min-height:40px;color:var(--text-secondary)}.block{display:block;margin:16px 0}</style>
